package com.hrflow.controller; import com.hrflow.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController@RequestMapping("/api/reports")@RequiredArgsConstructor public class ReportController{final EmployeeRepository employees;final AttendanceRepository attendance;final LeaveRequestRepository leaves;final PayrollRepository payroll;final CandidateRepository candidates;@GetMapping("/summary")public Map<String,Object> summary(){return Map.of("employees",employees.count(),"attendanceRecords",attendance.count(),"leaveRequests",leaves.count(),"payrollRecords",payroll.count(),"candidates",candidates.count());}}
